import DashboardLayout from "@/components/DashboardLayout";
import { RecordActions } from "@/components/RecordActions";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { demoRentalData } from "@/lib/demoRentalData";
import { formatPeriod } from "@shared/rentalCalculations";
import { TURKEY_DAILY_REMINDER_LABEL } from "@shared/reminderRules";
import { canMutateRecord } from "@shared/demoMode";
import { withListDemoFallback, withObjectDemoFallback } from "@shared/demoFallback";
import { AlertTriangle, Archive, ArrowDownToLine, BellRing, Building2, CircleDollarSign, ClipboardList, FileText, Landmark, LayoutDashboard, Package, Pencil, Plus, ReceiptText, RefreshCw, Trash2, UserRound, WalletCards } from "lucide-react";
import { createContext, useContext, useMemo, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

type ModuleKey = "dashboard" | "portfolio" | "tenants" | "contracts" | "charges" | "finance" | "inventory" | "archive" | "reminders" | "reports";
type FormState = { kind: string; data: Record<string, unknown> } | null;
type Field = { key: string; label: string; type?: "text" | "number" | "date" | "textarea" | "select" | "url" | "section"; options?: { value: string | number; label: string }[]; required?: boolean; hint?: string };
const DemoModeContext = createContext(false);

const moduleMeta: Record<ModuleKey, { title: string; caption: string; icon: typeof LayoutDashboard }> = {
  dashboard: { title: "Genel Bakış", caption: "Portföyünüzün güncel görünümü ve önemli hareketler.", icon: LayoutDashboard },
  portfolio: { title: "Gayrimenkul Portföyü", caption: "Site, bina ve bağımsız bölüm kayıtlarınızı hiyerarşik olarak yönetin.", icon: Building2 },
  tenants: { title: "Kiracılar", caption: "İletişim bilgileri ve ilişkilendirilmiş kiracılık kayıtları.", icon: UserRound },
  contracts: { title: "Kira Sözleşmeleri", caption: "Aktif sözleşmeler, kira şartları ve yenileme dönemleri.", icon: FileText },
  charges: { title: "Tahakkuk ve Tahsilatlar", caption: "Aylık kira borçlarını, ödemeleri ve gecikmeleri takip edin.", icon: WalletCards },
  finance: { title: "Gelir ve Giderler", caption: "Operasyonunuzun temel finansal görünümü.", icon: CircleDollarSign },
  inventory: { title: "Demirbaşlar", caption: "Taşınmazlara bağlı varlık ve ekipman kayıtları.", icon: Package },
  archive: { title: "Belge Arşivi", caption: "Sözleşme ve ilgili belge kayıtlarınızı düzenleyin.", icon: Archive },
  reminders: { title: "Hatırlatmalar", caption: "Yaklaşan sözleşmeler ve vadesi gelen tahsilatlar.", icon: BellRing },
  reports: { title: "Raporlar ve Yedekler", caption: "Dışa aktarım alın ve veri yedekleme kayıtlarınızı yönetin.", icon: ClipboardList },
};

const currency = new Intl.NumberFormat("tr-TR", { style: "currency", currency: "TRY", maximumFractionDigits: 0 });
const numberText = new Intl.NumberFormat("tr-TR");

function dateText(value?: string | Date | null) {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleDateString("tr-TR");
}

function dateValue(value?: string | Date | null) {
  if (!value) return "";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toISOString().slice(0, 10);
}

function money(value: string | number | null | undefined) {
  return currency.format(Number(value ?? 0));
}

function clean(data: Record<string, unknown>) {
  return Object.fromEntries(Object.entries(data).map(([key, value]) => [key, value === "" ? null : value]));
}

function statusBadge(status: string) {
  const styles: Record<string, string> = {
    aktif: "border-emerald-200 bg-emerald-50 text-emerald-700",
    dolu: "border-emerald-200 bg-emerald-50 text-emerald-700",
    odendi: "border-emerald-200 bg-emerald-50 text-emerald-700",
    bekliyor: "border-amber-200 bg-amber-50 text-amber-700",
    yaklasan: "border-amber-200 bg-amber-50 text-amber-700",
    gecikti: "border-rose-200 bg-rose-50 text-rose-700",
    sona_erdi: "border-slate-200 bg-slate-100 text-slate-600",
    bos: "border-sky-200 bg-sky-50 text-sky-700",
    pasif: "border-slate-200 bg-slate-100 text-slate-600",
    bakimda: "border-amber-200 bg-amber-50 text-amber-700",
    hurda: "border-rose-200 bg-rose-50 text-rose-700",
    hazir: "border-indigo-200 bg-indigo-50 text-indigo-700",
    arsivlendi: "border-slate-200 bg-slate-100 text-slate-600",
  };
  return <Badge variant="outline" className={`rounded-full px-2.5 py-0.5 font-medium ${styles[status] ?? "border-slate-200 bg-slate-50 text-slate-700"}`}>{status.replace("_", " ")}</Badge>;
}

function EmptyState({ title, detail, onCreate }: { title: string; detail: string; onCreate?: () => void }) {
  return <div className="flex min-h-40 flex-col items-center justify-center border-t border-slate-100 bg-slate-50/50 px-5 py-10 text-center"><p className="font-medium text-slate-700">{title}</p><p className="mt-1 max-w-md text-sm leading-6 text-slate-500">{detail}</p>{onCreate && <Button variant="outline" className="mt-4 rounded-md border-slate-300 bg-white text-slate-700 hover:bg-slate-50" onClick={onCreate}><Plus className="mr-2 h-4 w-4" />Kayıt oluştur</Button>}</div>;
}

function TableShell({ title, subtitle, action, children }: { title: string; subtitle: string; action?: React.ReactNode; children: React.ReactNode }) {
  return <Card className="overflow-hidden rounded-md border-slate-200 bg-white shadow-sm"><CardHeader className="flex flex-row items-start justify-between gap-4 border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-sm font-semibold text-slate-800">{title}</CardTitle><CardDescription className="mt-1 text-sm leading-5 text-slate-500">{subtitle}</CardDescription></div>{action}</CardHeader><CardContent className="p-0">{children}</CardContent></Card>;
}

function ActionButtons({ onEdit, onDelete, readOnly = false }: { onEdit: () => void; onDelete: () => void; readOnly?: boolean }) {
  const demoMode = useContext(DemoModeContext);
  return <RecordActions onEdit={onEdit} onDelete={onDelete} isReadOnly={!canMutateRecord(demoMode, readOnly)} />;
}

export default function RentalManager() {
  return <DashboardLayout><RentalContent /></DashboardLayout>;
}

function RentalContent() {
  const [location] = useLocation();
  const routeKey = location.replace("/", "") as ModuleKey;
  const active = moduleMeta[routeKey] ? routeKey : "dashboard";
  const meta = moduleMeta[active];
  const [form, setForm] = useState<FormState>(null);
  const utils = trpc.useUtils();

  const dashboard = trpc.rental.dashboard.summary.useQuery();
  const portfolio = trpc.rental.portfolio.list.useQuery();
  const tenantList = trpc.rental.tenants.list.useQuery();
  const contractList = trpc.rental.contracts.list.useQuery();
  const chargeList = trpc.rental.charges.list.useQuery();
  const finance = trpc.rental.finance.list.useQuery();
  const inventory = trpc.rental.inventory.list.useQuery();
  const archive = trpc.rental.archive.list.useQuery();
  const reminders = trpc.rental.reminders.list.useQuery();
  const reminderRule = trpc.rental.reminders.rule.useQuery();
  const reminderNotifications = trpc.rental.reminders.notifications.useQuery();
  const backups = trpc.rental.backups.list.useQuery();

  const invalidate = async () => {
    await Promise.all([
      utils.rental.dashboard.summary.invalidate(), utils.rental.portfolio.list.invalidate(), utils.rental.tenants.list.invalidate(), utils.rental.contracts.list.invalidate(), utils.rental.charges.list.invalidate(), utils.rental.finance.list.invalidate(), utils.rental.inventory.list.invalidate(), utils.rental.archive.list.invalidate(), utils.rental.reminders.list.invalidate(), utils.rental.backups.list.invalidate(),
    ]);
  };
  const showMutationError = (error: { message: string }) => toast.error(error.message);
  const mutationOptions = { onSuccess: () => { void invalidate(); setForm(null); toast.success("Kayıt başarıyla kaydedildi."); }, onError: showMutationError };
  const siteMutation = trpc.rental.portfolio.saveSite.useMutation(mutationOptions);
  const buildingMutation = trpc.rental.portfolio.saveBuilding.useMutation(mutationOptions);
  const unitMutation = trpc.rental.portfolio.saveUnit.useMutation(mutationOptions);
  const tenantMutation = trpc.rental.tenants.save.useMutation(mutationOptions);
  const contractMutation = trpc.rental.contracts.save.useMutation(mutationOptions);
  const chargeMutation = trpc.rental.charges.save.useMutation(mutationOptions);
  const financeMutation = trpc.rental.finance.save.useMutation(mutationOptions);
  const assetMutation = trpc.rental.inventory.save.useMutation(mutationOptions);
  const documentMutation = trpc.rental.archive.save.useMutation(mutationOptions);
  const backupMutation = trpc.rental.backups.record.useMutation(mutationOptions);
  const removePortfolio = trpc.rental.portfolio.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const removeTenant = trpc.rental.tenants.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const removeContract = trpc.rental.contracts.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const removeCharge = trpc.rental.charges.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const removeFinance = trpc.rental.finance.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const removeAsset = trpc.rental.inventory.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const removeDocument = trpc.rental.archive.remove.useMutation({ onSuccess: () => { void invalidate(); toast.success("Kayıt silindi."); }, onError: showMutationError });
  const enableDailyReminder = trpc.rental.reminders.enableDaily.useMutation({ onSuccess: async () => { await reminderRule.refetch(); toast.success("Günlük geciken kira hatırlatması etkinleştirildi."); }, onError: showMutationError });
  const disableDailyReminder = trpc.rental.reminders.disableDaily.useMutation({ onSuccess: async () => { await reminderRule.refetch(); toast.success("Günlük geciken kira hatırlatması duraklatıldı."); }, onError: showMutationError });

  const isLoading = [dashboard, portfolio, tenantList, contractList, chargeList, finance, inventory, archive, reminders, reminderNotifications, backups].some(query => query.isLoading);
  const portfolioHasData = Boolean(portfolio.data?.sites.length || portfolio.data?.buildings.length || portfolio.data?.units.length);
  const dashboardHasData = Boolean((dashboard.data?.unitCount ?? 0) || (dashboard.data?.tenantCount ?? 0) || (dashboard.data?.activeContractCount ?? 0) || Number(dashboard.data?.outstandingAmount ?? 0) || (dashboard.data?.overdueCount ?? 0));
  const remindersHasData = Boolean(reminders.data?.charges.length || reminders.data?.contracts.length);
  const dashboardFallback = withObjectDemoFallback<any>(dashboard.data, dashboardHasData, demoRentalData.dashboard);
  const portfolioFallback = withObjectDemoFallback<any>(portfolio.data, portfolioHasData, demoRentalData.portfolio);
  const tenantsFallback = withListDemoFallback<any>(tenantList.data, demoRentalData.tenants);
  const contractsFallback = withListDemoFallback<any>(contractList.data, demoRentalData.contracts);
  const chargesFallback = withListDemoFallback<any>(chargeList.data, demoRentalData.charges);
  const financeFallback = withObjectDemoFallback<any>(finance.data, Boolean(finance.data?.records.length), demoRentalData.finance);
  const inventoryFallback = withListDemoFallback<any>(inventory.data, demoRentalData.inventory);
  const archiveFallback = withListDemoFallback<any>(archive.data, demoRentalData.archive);
  const remindersFallback = withObjectDemoFallback<any>(reminders.data, remindersHasData, demoRentalData.reminders);
  const backupsFallback = withListDemoFallback<any>(backups.data, demoRentalData.backups);
  const pageUsesDemo: Record<ModuleKey, boolean> = { dashboard: dashboardFallback.isDemo, portfolio: portfolioFallback.isDemo, tenants: tenantsFallback.isDemo, contracts: contractsFallback.isDemo, charges: chargesFallback.isDemo, finance: financeFallback.isDemo, inventory: inventoryFallback.isDemo, archive: archiveFallback.isDemo, reminders: remindersFallback.isDemo, reports: backupsFallback.isDemo };
  const isDemo = !isLoading && pageUsesDemo[active];
  const dashboardData: any = dashboardFallback.data;
  const portfolioData: any = portfolioFallback.data;
  const tenantsData: any = tenantsFallback.data;
  const contractsData: any = contractsFallback.data;
  const chargesData: any = chargesFallback.data;
  const financeData: any = financeFallback.data;
  const inventoryData: any = inventoryFallback.data;
  const archiveData: any = archiveFallback.data;
  const remindersData: any = remindersFallback.data;
  const backupsData: any = backupsFallback.data;
  const hasPortfolio = Boolean(portfolioData?.sites.length || portfolioData?.buildings.length || portfolioData?.units.length);
  const fields = useMemo(() => getFields(form?.kind ?? "", portfolio.data, tenantList.data, contractList.data), [form?.kind, portfolio.data, tenantList.data, contractList.data]);

  const create = (kind: string) => {
    const base = initialData(kind, portfolio.data, tenantList.data, contractList.data);
    const unitDefaults = kind === "unit" ? { netArea: "", roomCount: "", targetRent: "", monthlyDues: "", furnished: "hayir", parkingSlot: "", electricityMeterNo: "", waterMeterNo: "", naturalGasMeterNo: "" } : {};
    setForm({ kind, data: { ...base, ...unitDefaults } });
  };
  const edit = (kind: string, row: Record<string, unknown>) => setForm({ kind, data: normalizeForEdit(kind, row) });
  const confirmDelete = (kind: string, id: number) => {
    if (!window.confirm("Bu kaydı silmek istediğinize emin misiniz? Bağlı kayıtlar varsa önce onları düzenlemeniz gerekebilir.")) return;
    if (kind === "site" || kind === "building" || kind === "unit") removePortfolio.mutate({ type: kind, id });
    else if (kind === "tenant") removeTenant.mutate(id);
    else if (kind === "contract") removeContract.mutate(id);
    else if (kind === "charge") removeCharge.mutate(id);
    else if (kind === "finance") removeFinance.mutate(id);
    else if (kind === "asset") removeAsset.mutate(id);
    else if (kind === "document") removeDocument.mutate(id);
  };
  const save = async (event: React.FormEvent) => {
    event.preventDefault(); if (!form) return;
    const payload = clean(form.data) as any;
    try {
      if (form.kind === "site") await siteMutation.mutateAsync(payload);
      if (form.kind === "building") await buildingMutation.mutateAsync(payload);
      if (form.kind === "unit") await unitMutation.mutateAsync(payload);
      if (form.kind === "tenant") await tenantMutation.mutateAsync(payload);
      if (form.kind === "contract") await contractMutation.mutateAsync(payload);
      if (form.kind === "charge") await chargeMutation.mutateAsync(payload);
      if (form.kind === "finance") await financeMutation.mutateAsync(payload);
      if (form.kind === "asset") await assetMutation.mutateAsync(payload);
      if (form.kind === "document") await documentMutation.mutateAsync(payload);
      if (form.kind === "backup") await backupMutation.mutateAsync(payload);
    } catch { /* Mutation callback presents the error. */ }
  };
  const exportReport = () => {
    const rows: any[] = financeData?.records ?? [];
    const header = "Tarih,Tür,Kategori,Tutar,Açıklama";
    const lines = rows.map(item => [dateValue(item.recordDate), item.kind, item.category, item.amount, item.description ?? ""].map(value => `"${String(value).replaceAll('"', '""')}"`).join(","));
    const blob = new Blob([[header, ...lines].join("\n")], { type: "text/csv;charset=utf-8" });
    const href = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = href; link.download = `kira-takip-finans-${formatPeriod(new Date())}.csv`; link.click(); URL.revokeObjectURL(href); toast.success("Finans raporu CSV olarak indirildi.");
  };
  const Icon = meta.icon;

  return <DemoModeContext.Provider value={isDemo}><div className="app-workspace min-h-[calc(100vh-2rem)] p-1 sm:p-5">
    <header className="mb-6 flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
      <div><div className="mb-2 flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.12em] text-slate-500"><Icon className="h-3.5 w-3.5" />Kira Takip / Yönetim</div><h1 className="text-2xl font-semibold tracking-tight text-slate-900 sm:text-3xl">{meta.title}</h1><p className="mt-1.5 max-w-2xl text-sm leading-6 text-slate-500">{meta.caption}</p></div>
      {active !== "dashboard" && active !== "reminders" && <Button onClick={() => create(primaryKind(active))} className="h-10 rounded-xl bg-emerald-800 px-4 font-medium text-white shadow-[0_8px_20px_rgba(6,78,59,0.18)] hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Yeni kayıt</Button>}
    </header>

    {isDemo && <div className="mb-5 flex flex-col gap-1 rounded-md border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-900 sm:flex-row sm:items-center sm:justify-between"><span><strong>Örnek görünüm:</strong> Bu ekranlardaki kayıtlar statiktir; ilk gerçek kaydı eklediğinizde yalnızca kendi verileriniz gösterilir.</span><span className="text-xs font-medium text-blue-700">Salt okunur örnek kayıtlar</span></div>}
    {form && <form onSubmit={save} className="mb-6 overflow-hidden rounded-2xl border border-emerald-200 bg-white shadow-[0_18px_40px_rgba(41,54,40,0.10)]"><div className="flex flex-col gap-3 border-b border-stone-100 bg-emerald-50/60 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-emerald-700">Kayıt düzenleyici</p><h2 className="mt-1 text-lg font-semibold text-stone-900">{form.data.id ? "Kaydı düzenle" : "Yeni kayıt ekle"}</h2></div><Button type="button" variant="ghost" className="rounded-xl text-stone-600" onClick={() => setForm(null)}>Vazgeç</Button></div><div className="grid gap-x-5 gap-y-4 p-5 md:grid-cols-2 xl:grid-cols-3">{fields.map(field => <FormField key={field.key} field={field} value={form.data[field.key]} onChange={value => setForm(current => current ? { ...current, data: { ...current.data, [field.key]: value } } : current)} />)}</div><div className="flex justify-end gap-3 border-t border-stone-100 bg-stone-50/70 px-5 py-4"><Button type="button" variant="outline" className="rounded-xl bg-white" onClick={() => setForm(null)}>İptal</Button><Button type="submit" className="rounded-xl bg-emerald-800 hover:bg-emerald-900" disabled={siteMutation.isPending || buildingMutation.isPending || unitMutation.isPending || tenantMutation.isPending || contractMutation.isPending || chargeMutation.isPending || financeMutation.isPending || assetMutation.isPending || documentMutation.isPending || backupMutation.isPending}>{form.data.id ? "Değişiklikleri kaydet" : "Kaydı oluştur"}</Button></div></form>}

    {isLoading ? <DashboardSkeleton /> : <main>{active === "dashboard" && <DashboardView summary={dashboardData} hasPortfolio={hasPortfolio} onCreatePortfolio={() => create("site")} onCreateCharge={() => create("charge")} />}{active === "portfolio" && <PortfolioView data={portfolioData} onCreate={create} onEdit={edit} onDelete={confirmDelete} />}{active === "tenants" && <TenantsView data={tenantsData} onCreate={() => create("tenant")} onEdit={edit} onDelete={confirmDelete} />}{active === "contracts" && <ContractsView data={contractsData} onCreate={() => create("contract")} onEdit={edit} onDelete={confirmDelete} />}{active === "charges" && <ChargesView data={chargesData} onCreate={() => create("charge")} onEdit={edit} onDelete={confirmDelete} />}{active === "finance" && <FinanceView data={financeData} onCreate={() => create("finance")} onEdit={edit} onDelete={confirmDelete} />}{active === "inventory" && <InventoryView data={inventoryData} onCreate={() => create("asset")} onEdit={edit} onDelete={confirmDelete} />}{active === "archive" && <ArchiveView data={archiveData} onCreate={() => create("document")} onEdit={edit} onDelete={confirmDelete} />}{active === "reminders" && <RemindersView data={remindersData} notifications={reminderNotifications.data} rule={reminderRule.data} onEnable={() => enableDailyReminder.mutate()} onDisable={() => disableDailyReminder.mutate()} pending={enableDailyReminder.isPending || disableDailyReminder.isPending} />}{active === "reports" && <ReportsView data={backupsData} onCreate={() => create("backup")} onExport={exportReport} />}</main>}
  </div></DemoModeContext.Provider>;
}

function FormField({ field, value, onChange }: { field: Field; value: unknown; onChange: (value: string) => void }) {
  const id = `field-${field.key}`;
  if (field.type === "section") return <div className="col-span-full mt-1 border-b border-slate-200 pb-2 pt-2"><p className="text-xs font-semibold uppercase tracking-[0.1em] text-slate-500">{field.label}</p>{field.hint && <p className="mt-1 text-xs text-slate-400">{field.hint}</p>}</div>;
  return <div className={field.type === "textarea" ? "md:col-span-2 xl:col-span-3" : ""}><Label htmlFor={id} className="mb-2 block text-sm font-medium text-stone-700">{field.label}{field.required && <span className="ml-1 text-rose-500">*</span>}</Label>{field.type === "textarea" ? <Textarea id={id} value={String(value ?? "")} onChange={event => onChange(event.target.value)} className="min-h-24 rounded-xl border-stone-200 bg-white" /> : field.type === "select" ? <select id={id} value={String(value ?? "")} onChange={event => onChange(event.target.value)} className="h-10 w-full rounded-xl border border-stone-200 bg-white px-3 text-sm text-stone-800 shadow-sm outline-none transition focus:border-emerald-600 focus:ring-3 focus:ring-emerald-100"><option value="">Seçiniz</option>{field.options?.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : <Input id={id} type={field.type ?? "text"} required={field.required} value={field.type === "date" ? dateValue(value as string | Date | null) : String(value ?? "")} onChange={event => onChange(event.target.value)} className="h-10 rounded-xl border-stone-200 bg-white" />}{field.hint && <p className="mt-1.5 text-xs leading-5 text-stone-500">{field.hint}</p>}</div>;
}

function DashboardSkeleton() { return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{Array.from({ length: 4 }).map((_, index) => <Skeleton key={index} className="h-34 rounded-2xl bg-stone-200/60" />)}<Skeleton className="h-80 rounded-2xl bg-stone-200/60 sm:col-span-2 xl:col-span-4" /></div>; }

function DashboardView({ summary, hasPortfolio, onCreatePortfolio, onCreateCharge }: { summary: any; hasPortfolio: boolean; onCreatePortfolio: () => void; onCreateCharge: () => void }) {
  const occupiedCount = summary?.occupiedUnitCount ?? summary?.activeContractCount ?? 0;
  const availableCount = summary?.availableUnitCount ?? Math.max((summary?.unitCount ?? 0) - occupiedCount, 0);
  const cards = [{ label: "Dolu daire", value: numberText.format(occupiedCount), icon: Building2 }, { label: "Boş daire", value: numberText.format(availableCount), icon: Building2 }, { label: "Geciken tahsilat", value: numberText.format(summary?.overdueCount ?? 0), icon: ReceiptText }, { label: "Açık alacak", value: money(summary?.outstandingAmount), icon: WalletCards }];
  const overdueCharges = summary?.overdueCharges ?? [];
  return <div className="space-y-4"><div className="grid divide-y divide-slate-200 overflow-hidden rounded-md border border-slate-200 bg-white sm:grid-cols-2 sm:divide-x sm:divide-y-0 xl:grid-cols-4">{cards.map(card => <div key={card.label} className="flex items-start justify-between p-4"><div><p className="text-xs font-medium uppercase tracking-[0.08em] text-slate-500">{card.label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">{card.value}</p></div><card.icon className="h-4 w-4 text-slate-400" /></div>)}</div>{overdueCharges.length > 0 && <Card className="overflow-hidden border-rose-200 bg-white shadow-sm"><CardHeader className="border-b border-rose-100 bg-rose-50 px-5 py-4"><CardTitle className="flex items-center gap-2 text-sm font-semibold text-rose-900"><AlertTriangle className="h-4 w-4" />Geciken kira tahsilatları</CardTitle><CardDescription className="text-rose-700">Vadesi geçmiş ve tam tahsil edilmemiş kayıtlar öncelikli takip gerektirir.</CardDescription></CardHeader><CardContent className="p-0"><div className="divide-y divide-rose-100">{overdueCharges.map((charge: any) => <div key={charge.id} className="flex flex-col gap-2 px-5 py-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-slate-900">{charge.tenantName || "Kiracı"} <span className="font-normal text-slate-500">· {charge.unitNumber || "Bölüm"}</span></p><p className="mt-0.5 text-sm text-slate-500">Vade: {dateText(charge.dueDate)}</p></div><p className="font-semibold text-rose-700">{money(charge.remaining)} gecikmiş</p></div>)}</div></CardContent></Card>}<div className="grid gap-4 xl:grid-cols-[1.4fr_.6fr]"><TableShell title="Kurulum ve işlem merkezi" subtitle="Portföy, kiracı, sözleşme ve tahsilat kayıtlarını bu sıralamayla tamamlayın.">{!hasPortfolio ? <EmptyState title="Portföy kaydı bulunmuyor" detail="Önce siteyi, ardından bina ve bağımsız bölümleri kaydederek kira işlemlerini başlatın." onCreate={onCreatePortfolio} /> : <div className="grid gap-3 p-4 sm:grid-cols-2"><button onClick={onCreatePortfolio} className="rounded-md border border-slate-200 p-4 text-left transition hover:border-blue-300 hover:bg-blue-50"><Building2 className="h-4 w-4 text-blue-600" /><p className="mt-3 text-sm font-semibold text-slate-800">Portföye kayıt ekle</p><p className="mt-1 text-sm leading-5 text-slate-500">Site, bina veya bağımsız bölüm tanımlayın.</p></button><button onClick={onCreateCharge} className="rounded-md border border-slate-200 p-4 text-left transition hover:border-blue-300 hover:bg-blue-50"><ReceiptText className="h-4 w-4 text-blue-600" /><p className="mt-3 text-sm font-semibold text-slate-800">Tahakkuk oluştur</p><p className="mt-1 text-sm leading-5 text-slate-500">Yeni dönem kira borcunu kaydedin.</p></button></div>}</TableShell><Card className="rounded-md border-slate-200 bg-white shadow-sm"><CardContent className="border-l-4 border-amber-400 p-5"><p className="text-xs font-semibold uppercase tracking-[0.1em] text-slate-500">Dikkat gerektirenler</p><p className="mt-2 text-2xl font-semibold text-slate-900">{summary?.overdueCount ?? 0}</p><p className="mt-1 text-sm leading-6 text-slate-500">Gecikmiş tahakkuk kaydı. Ayrıntılar için Hatırlatmalar ekranını açın.</p><Button variant="link" className="mt-3 h-auto p-0 text-blue-600">Hatırlatmaları görüntüle</Button></CardContent></Card></div></div>;
}

function PortfolioView({ data, onCreate, onEdit, onDelete, readOnly = false }: { data: any; onCreate: (kind: string) => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void; readOnly?: boolean }) { return <div className="space-y-5"><TableShell title="Siteler" subtitle="Gayrimenkul portföyünüzün üst seviyesi." action={<Button onClick={() => onCreate("site")} size="sm" className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-1.5 h-4 w-4" />Site ekle</Button>}>{data?.sites?.length ? <DataTable headers={["Site adı", "Adres", "Not", ""]}>{data.sites.map((item: any) => <tr key={item.id}><td className="font-medium text-stone-800">{item.name}</td><td>{item.address || "—"}</td><td>{item.notes || "—"}</td><td><ActionButtons onEdit={() => onEdit("site", item)} onDelete={() => onDelete("site", item.id)} readOnly={readOnly} /></td></tr>)}</DataTable> : <EmptyState title="Henüz site kaydı yok" detail="Portföyünüz için ilk siteyi ekleyin." onCreate={() => onCreate("site")} />}</TableShell><div className="grid gap-5 xl:grid-cols-2"><TableShell title="Binalar" subtitle="Siteler altında blok veya bina tanımları." action={<Button onClick={() => onCreate("building")} size="sm" variant="outline" className="rounded-xl"><Plus className="mr-1.5 h-4 w-4" />Bina ekle</Button>}>{data?.buildings?.length ? <DataTable headers={["Bina", "Blok", "Adres", ""]}>{data.buildings.map((item: any) => <tr key={item.id}><td className="font-medium text-stone-800">{item.name}</td><td>{item.block || "—"}</td><td>{item.address || "—"}</td><td><ActionButtons onEdit={() => onEdit("building", item)} onDelete={() => onDelete("building", item.id)} readOnly={readOnly} /></td></tr>)}</DataTable> : <EmptyState title="Henüz bina kaydı yok" detail="Bina eklemek için önce bir site oluşturun." onCreate={() => onCreate("building")} />}</TableShell><TableShell title="Bağımsız bölümler" subtitle="Daire, ofis, dükkan veya diğer birimler." action={<Button onClick={() => onCreate("unit")} size="sm" variant="outline" className="rounded-xl"><Plus className="mr-1.5 h-4 w-4" />Bölüm ekle</Button>}>{data?.units?.length ? <DataTable headers={["No", "Tip", "Kat", "Durum", ""]}>{data.units.map((item: any) => <tr key={item.id}><td className="font-medium text-stone-800">{item.unitNumber}</td><td>{item.unitType || "—"}</td><td>{item.floor || "—"}</td><td>{statusBadge(item.status)}</td><td><ActionButtons onEdit={() => onEdit("unit", item)} onDelete={() => onDelete("unit", item.id)} readOnly={readOnly} /></td></tr>)}</DataTable> : <EmptyState title="Henüz bağımsız bölüm yok" detail="Daire veya diğer bağımsız bölümleri kaydedin." onCreate={() => onCreate("unit")} />}</TableShell></div></div>; }
function TenantsView({ data, onCreate, onEdit, onDelete }: { data: any[] | undefined; onCreate: () => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void }) { return <TableShell title="Kiracı listesi" subtitle="İletişim, kimlik ve acil durum iletişim bilgileri." action={<Button onClick={onCreate} className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Kiracı ekle</Button>}>{data?.length ? <DataTable headers={["Kiracı", "Telefon", "E-posta", "Acil iletişim", ""]}>{data.map(item => <tr key={item.id}><td className="font-medium text-stone-800">{item.fullName}</td><td>{item.phone || "—"}</td><td>{item.email || "—"}</td><td>{item.emergencyContact || "—"}</td><td><ActionButtons onEdit={() => onEdit("tenant", item)} onDelete={() => onDelete("tenant", item.id)} /></td></tr>)}</DataTable> : <EmptyState title="Henüz kiracı kaydı yok" detail="Sözleşme oluşturabilmek için önce bir kiracı tanımlayın." onCreate={onCreate} />}</TableShell>; }
function ContractsView({ data, onCreate, onEdit, onDelete }: { data: any[] | undefined; onCreate: () => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void }) { return <TableShell title="Sözleşmeler" subtitle="Daire-kiracı eşleşmeleri ile kira koşulları." action={<Button onClick={onCreate} className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Sözleşme ekle</Button>}>{data?.length ? <DataTable headers={["Kiracı", "Bölüm", "Dönem", "Aylık kira", "Durum", ""]}>{data.map(item => <tr key={item.contract.id}><td className="font-medium text-stone-800">{item.tenantName || "—"}</td><td>{item.buildingName ? `${item.buildingName} · ${item.unitNumber}` : item.unitNumber || "—"}</td><td>{dateText(item.contract.startDate)} — {dateText(item.contract.endDate)}</td><td className="font-medium text-stone-800">{money(item.contract.monthlyRent)}</td><td>{statusBadge(item.contract.status)}</td><td><ActionButtons onEdit={() => onEdit("contract", item.contract)} onDelete={() => onDelete("contract", item.contract.id)} /></td></tr>)}</DataTable> : <EmptyState title="Henüz sözleşme kaydı yok" detail="Bir bağımsız bölümü kiracıyla eşleştirerek ilk sözleşmeyi oluşturun." onCreate={onCreate} />}</TableShell>; }
function ChargesView({ data, onCreate, onEdit, onDelete }: { data: any[] | undefined; onCreate: () => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void }) { return <TableShell title="Aylık tahakkuklar" subtitle="Tahsil edilen, bekleyen ve geciken kira kayıtları." action={<Button onClick={onCreate} className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Tahakkuk ekle</Button>}>{data?.length ? <DataTable headers={["Dönem", "Kiracı", "Bölüm", "Vade", "Tutar", "Durum", ""]}>{data.map(item => <tr key={item.charge.id}><td className="font-medium text-stone-800">{item.charge.period}</td><td>{item.tenantName || "—"}</td><td>{item.unitNumber || "—"}</td><td>{dateText(item.charge.dueDate)}</td><td>{money(item.charge.paidAmount)} <span className="text-stone-400">/ {money(item.charge.amount)}</span></td><td>{statusBadge(item.charge.status)}</td><td><ActionButtons onEdit={() => onEdit("charge", item.charge)} onDelete={() => onDelete("charge", item.charge.id)} /></td></tr>)}</DataTable> : <EmptyState title="Henüz tahakkuk kaydı yok" detail="Bir sözleşme için aylık kira borcu oluşturduğunuzda takip otomatik durum etiketiyle başlar." onCreate={onCreate} />}</TableShell>; }
function FinanceView({ data, onCreate, onEdit, onDelete }: { data: any; onCreate: () => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void }) { return <div className="space-y-5"><div className="grid gap-4 md:grid-cols-3"><MetricCard label="Toplam gelir" value={money(data?.summary?.gelir)} tone="emerald" /><MetricCard label="Toplam gider" value={money(data?.summary?.gider)} tone="rose" /><MetricCard label="Net bakiye" value={money(data?.summary?.net)} tone="amber" /></div><TableShell title="Finans hareketleri" subtitle="Gelir ve gider kayıtlarının tüm zamanlar görünümü." action={<Button onClick={onCreate} className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Hareket ekle</Button>}>{data?.records?.length ? <DataTable headers={["Tarih", "Tür", "Kategori", "Açıklama", "Tutar", ""]}>{data.records.map((item: any) => <tr key={item.id}><td>{dateText(item.recordDate)}</td><td>{statusBadge(item.kind)}</td><td className="font-medium text-stone-800">{item.category}</td><td>{item.description || "—"}</td><td className={item.kind === "gelir" ? "font-medium text-emerald-700" : "font-medium text-rose-700"}>{item.kind === "gelir" ? "+" : "−"}{money(item.amount)}</td><td><ActionButtons onEdit={() => onEdit("finance", item)} onDelete={() => onDelete("finance", item.id)} /></td></tr>)}</DataTable> : <EmptyState title="Henüz finans hareketi yok" detail="Kira geliri, bakım gideri ve diğer operasyon kalemlerini kaydedebilirsiniz." onCreate={onCreate} />}</TableShell></div>; }
function InventoryView({ data, onCreate, onEdit, onDelete }: { data: any[] | undefined; onCreate: () => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void }) { return <TableShell title="Demirbaş envanteri" subtitle="Bağımsız bölümlere atanabilen ekipman ve varlık kayıtları." action={<Button onClick={onCreate} className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Demirbaş ekle</Button>}>{data?.length ? <DataTable headers={["Varlık", "Kategori", "Alım tarihi", "Maliyet", "Durum", ""]}>{data.map(item => <tr key={item.id}><td className="font-medium text-stone-800">{item.name}</td><td>{item.category}</td><td>{dateText(item.acquisitionDate)}</td><td>{money(item.cost)}</td><td>{statusBadge(item.status)}</td><td><ActionButtons onEdit={() => onEdit("asset", item)} onDelete={() => onDelete("asset", item.id)} /></td></tr>)}</DataTable> : <EmptyState title="Henüz demirbaş kaydı yok" detail="Varlıklarınızın maliyetini ve durumunu buradan takip edebilirsiniz." onCreate={onCreate} />}</TableShell>; }
function ArchiveView({ data, onCreate, onEdit, onDelete }: { data: any[] | undefined; onCreate: () => void; onEdit: (kind: string, row: any) => void; onDelete: (kind: string, id: number) => void }) { return <TableShell title="Belge kayıtları" subtitle="Dosya adı ve erişim bağlantısı ile sözleşme veya ilgili dokümanları ilişkilendirin." action={<Button onClick={onCreate} className="rounded-xl bg-emerald-800 hover:bg-emerald-900"><Plus className="mr-2 h-4 w-4" />Belge ekle</Button>}>{data?.length ? <DataTable headers={["Başlık", "Kategori", "Dosya", "Bağlantı", ""]}>{data.map(item => <tr key={item.id}><td className="font-medium text-stone-800">{item.title}</td><td>{statusBadge(item.category)}</td><td>{item.fileName || "—"}</td><td>{item.externalUrl ? <a className="text-emerald-700 underline underline-offset-4" href={item.externalUrl} target="_blank" rel="noreferrer">Aç</a> : "—"}</td><td><ActionButtons onEdit={() => onEdit("document", item)} onDelete={() => onDelete("document", item.id)} /></td></tr>)}</DataTable> : <EmptyState title="Henüz belge kaydı yok" detail="Sözleşme, tahsilat dekontu veya diğer belgeler için arşiv kaydı ekleyin." onCreate={onCreate} />}</TableShell>; }
function RemindersView({ data, notifications, rule, onEnable, onDisable, pending }: { data: any; notifications: any[] | undefined; rule: any; onEnable: () => void; onDisable: () => void; pending: boolean }) { const charges = data?.charges ?? []; const contracts = data?.contracts ?? []; const enabled = rule?.status === "aktif"; const canManage = rule?.canManage !== false; return <div className="space-y-5"><Card className="border-blue-200 bg-blue-50/60 shadow-sm"><CardContent className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2"><BellRing className="h-4 w-4 text-blue-700" /><p className="font-semibold text-slate-900">Geciken kira için otomatik hatırlatma</p>{enabled && <Badge className="bg-blue-600 text-white">Etkin</Badge>}</div><p className="mt-1.5 text-sm leading-6 text-slate-600">Geciken tahsilatlar her gün kontrol edilir; bulunduğunda hesabınıza uygulama içi bildirim kaydı bırakılır. Çalışma saati: {TURKEY_DAILY_REMINDER_LABEL}.</p>{rule?.lastRunAt && <p className="mt-1 text-xs text-slate-500">Son kontrol: {dateText(rule.lastRunAt)} · {rule.lastOverdueCount ?? 0} geciken kayıt</p>}</div><Button onClick={enabled ? onDisable : onEnable} disabled={pending || !canManage} className={enabled ? "rounded-md bg-slate-800 hover:bg-slate-900" : "rounded-md bg-blue-600 hover:bg-blue-700"}>{!canManage ? "Yalnızca proje sahibi" : enabled ? "Hatırlatmayı duraklat" : "Kuralı başlat"}</Button></CardContent></Card>{notifications?.length ? <TableShell title="Uygulama içi hatırlatmalar" subtitle="Günlük kontrol sonucunda hesabınıza kaydedilen son bildirimler."><div className="divide-y divide-slate-100">{notifications.map(item => <div key={item.id} className="px-5 py-3"><p className="font-medium text-slate-900">{item.title}</p><p className="mt-1 whitespace-pre-line text-sm leading-5 text-slate-600">{item.content}</p><p className="mt-1.5 text-xs text-slate-400">{dateText(item.createdAt)}</p></div>)}</div></TableShell> : null}<div className="grid gap-5 xl:grid-cols-2"><TableShell title="Yaklaşan veya geciken tahsilatlar" subtitle="Ödenmemiş ve önümüzdeki 30 gün içindeki vadesi bulunan tahakkuklar.">{charges.length ? <div className="divide-y divide-stone-100">{charges.map((item: any) => <div key={item.id} className="flex items-center justify-between gap-4 px-5 py-4"><div><p className="font-medium text-stone-800">{item.tenantName || "Kiracı"} · {item.unitNumber || "Bölüm"}</p><p className="mt-1 text-sm text-stone-500">Vade: {dateText(item.dueDate)} · Kalan: {money(Number(item.amount) - Number(item.paidAmount))}</p></div>{statusBadge(item.status)}</div>)}</div> : <EmptyState title="Tahsilat hatırlatması bulunmuyor" detail="Gecikmiş veya yaklaşan vadesi olan ödenmemiş tahakkuklar burada görünür." />}</TableShell><TableShell title="Süresi yaklaşan sözleşmeler" subtitle="Önümüzdeki 30 gün içinde bitecek aktif sözleşmeler.">{contracts.length ? <div className="divide-y divide-stone-100">{contracts.map((item: any) => <div key={item.id} className="flex items-center justify-between gap-4 px-5 py-4"><div><p className="font-medium text-stone-800">{item.tenantName || "Kiracı"} · {item.unitNumber || "Bölüm"}</p><p className="mt-1 text-sm text-stone-500">Sözleşme bitişi: {dateText(item.endDate)}</p></div><Badge variant="outline" className="border-amber-200 bg-amber-50 text-amber-700">Yaklaşıyor</Badge></div>)}</div> : <EmptyState title="Yaklaşan sözleşme bitişi yok" detail="Bitiş tarihi önümüzdeki 30 gün içinde olan sözleşmeler burada listelenir." />}</TableShell></div></div>; }
function ReportsView({ data, onCreate, onExport }: { data: any[] | undefined; onCreate: () => void; onExport: () => void }) { return <div className="space-y-5"><div className="grid gap-5 lg:grid-cols-2"><Card className="border-stone-200 bg-white shadow-[0_10px_30px_rgba(57,45,32,0.05)]"><CardContent className="p-6"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700"><ArrowDownToLine className="h-5 w-5" /></div><h2 className="mt-5 text-lg font-semibold text-stone-900">Finans özeti dışa aktarımı</h2><p className="mt-2 text-sm leading-6 text-stone-500">Gelir ve gider hareketlerinizi Türkçe karakter uyumlu CSV dosyası olarak alın.</p><Button onClick={onExport} className="mt-5 rounded-xl bg-emerald-800 hover:bg-emerald-900"><ArrowDownToLine className="mr-2 h-4 w-4" />CSV indir</Button></CardContent></Card><Card className="border-stone-200 bg-[#f8f4eb] shadow-[0_10px_30px_rgba(57,45,32,0.05)]"><CardContent className="p-6"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-amber-100 text-amber-800"><RefreshCw className="h-5 w-5" /></div><h2 className="mt-5 text-lg font-semibold text-stone-900">Yedekleme kaydı</h2><p className="mt-2 text-sm leading-6 text-stone-600">Veri envanterinizin yedekleme işlemlerini kayıt altına alın ve izleyin.</p><Button onClick={onCreate} variant="outline" className="mt-5 rounded-xl border-amber-300 bg-white text-amber-900 hover:bg-amber-50"><Plus className="mr-2 h-4 w-4" />Yedekleme kaydı ekle</Button></CardContent></Card></div><TableShell title="Yedekleme kayıtları" subtitle="Oluşturduğunuz yedekleme envanteri kayıtları.">{data?.length ? <DataTable headers={["Kayıt adı", "Kapsam", "Kayıt sayısı", "Tarih", "Durum"]}>{data.map(item => <tr key={item.id}><td className="font-medium text-stone-800">{item.label}</td><td>{item.scope}</td><td>{numberText.format(item.recordCount)}</td><td>{dateText(item.createdAt)}</td><td>{statusBadge(item.status)}</td></tr>)}</DataTable> : <EmptyState title="Henüz yedekleme kaydı yok" detail="Yedekleme işlemleriniz için ilk kayıt görünümünü oluşturabilirsiniz." onCreate={onCreate} />}</TableShell></div>; }
function MetricCard({ label, value, tone }: { label: string; value: string; tone: "emerald" | "rose" | "amber" }) { const accent = { emerald: "border-l-emerald-500", rose: "border-l-rose-500", amber: "border-l-amber-500" }; return <Card className={`rounded-md border-slate-200 border-l-4 ${accent[tone]} bg-white shadow-sm`}><CardContent className="p-4"><p className="text-xs font-medium uppercase tracking-[0.08em] text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">{value}</p></CardContent></Card>; }
function DataTable({ headers, children }: { headers: string[]; children: React.ReactNode }) { return <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead className="bg-slate-50 text-xs font-semibold uppercase tracking-[0.08em] text-slate-500"><tr>{headers.map((header, index) => <th key={`${header}-${index}`} className="whitespace-nowrap px-4 py-3">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100 text-slate-600 [&_tr]:transition-colors [&_tr:hover]:bg-slate-50 [&_td]:px-4 [&_td]:py-3">{children}</tbody></table></div>; }

function primaryKind(active: ModuleKey) { return ({ portfolio: "site", tenants: "tenant", contracts: "contract", charges: "charge", finance: "finance", inventory: "asset", archive: "document", reports: "backup" } as Partial<Record<ModuleKey, string>>)[active] ?? "site"; }
function initialData(kind: string, portfolio: any, tenantList: any, contracts: any): Record<string, unknown> { const today = new Date(); const todayKey = dateValue(today); const firstSite = portfolio?.sites?.[0]?.id ?? ""; const firstBuilding = portfolio?.buildings?.[0]?.id ?? ""; const firstUnit = portfolio?.units?.[0]?.id ?? ""; const firstTenant = tenantList?.[0]?.id ?? ""; const firstContract = contracts?.[0]?.contract?.id ?? ""; const base: Record<string, Record<string, unknown>> = { site: { name: "", address: "", notes: "" }, building: { siteId: firstSite, name: "", block: "", address: "", notes: "" }, unit: { buildingId: firstBuilding, unitNumber: "", floor: "", unitType: "Daire", grossArea: "", status: "bos", notes: "" }, tenant: { fullName: "", identityNumber: "", phone: "", email: "", emergencyContact: "", notes: "" }, contract: { unitId: firstUnit, tenantId: firstTenant, startDate: todayKey, endDate: dateValue(new Date(today.getFullYear() + 1, today.getMonth(), today.getDate())), monthlyRent: "", increasePeriodMonths: 12, securityDeposit: "", paymentDay: 1, status: "aktif", notes: "" }, charge: { contractId: firstContract, period: formatPeriod(today), dueDate: todayKey, amount: "", paidAmount: 0, paidAt: "", notes: "" }, finance: { kind: "gelir", category: "Kira geliri", recordDate: todayKey, amount: "", unitId: "", contractId: "", description: "" }, asset: { unitId: firstUnit, name: "", category: "", acquisitionDate: todayKey, cost: 0, status: "aktif", notes: "" }, document: { title: "", category: "sozlesme", contractId: "", unitId: "", tenantId: "", fileName: "", externalUrl: "", notes: "" }, backup: { label: `Manuel yedek · ${todayKey}`, scope: "Tüm veriler" } }; return base[kind] ?? {}; }
function normalizeForEdit(kind: string, row: Record<string, any>): Record<string, unknown> { const dates = kind === "contract" ? ["startDate", "endDate"] : kind === "charge" ? ["dueDate", "paidAt"] : kind === "finance" ? ["recordDate"] : kind === "asset" ? ["acquisitionDate"] : []; const copy = { ...row }; dates.forEach(key => { copy[key] = dateValue(copy[key]); }); return copy; }
